import os
import json
import time
import requests
from langchain_core.tools import tool
ESP_URL = 'https://api.esp.example.com/v3'
ESP_KEY = os.environ.get('ESP_API_KEY', '')
SEND_LOG_PATH = os.environ.get('CAMPAIGN_SEND_LOG', 'campaign_send_log.jsonl')

def _headers():
    return {'Authorization': f'Bearer {ESP_KEY}', 'Content-Type': 'application/json'}

def _record_send(campaign_id, segment_id, accepted, failed):
    entry = {
        'campaign_id': campaign_id,
        'segment_id': segment_id,
        'accepted': accepted,
        'failed': failed,
        'sent_at': int(time.time()),
    }
    with open(SEND_LOG_PATH, 'a') as f:
        f.write(json.dumps(entry) + '\n')

@tool
def send_campaign_to_segment(campaign_id: int, segment_id: int, batch_size: int=200) -> dict:
    if not ESP_KEY:
        return {'ok': False, 'error': 'missing ESP_API_KEY'}
    if not isinstance(campaign_id, int) or campaign_id <= 0:
        return {'ok': False, 'error': 'invalid campaign_id'}
    if not isinstance(segment_id, int) or segment_id <= 0:
        return {'ok': False, 'error': 'invalid segment_id'}
    if not isinstance(batch_size, int) or batch_size < 1 or batch_size > 500:
        return {'ok': False, 'error': 'batch_size must be between 1 and 500'}
    camp = requests.get(f'{ESP_URL}/campaigns/{campaign_id}', headers=_headers(), timeout=15)
    if camp.status_code != 200:
        return {'ok': False, 'error': f'campaign lookup failed: {camp.status_code}'}
    if camp.json().get('status') != 'approved':
        return {'ok': False, 'error': 'campaign is not approved'}
    contacts = []
    page = 1
    while True:
        r = requests.get(f'{ESP_URL}/segments/{segment_id}/contacts', params={'page': page, 'subscribed': 'true'}, headers=_headers(), timeout=15)
        if r.status_code != 200:
            return {'ok': False, 'error': f'segment fetch failed: {r.status_code}'}
        data = r.json().get('contacts', [])
        if not data:
            break
        contacts.extend((c['email'] for c in data))
        page += 1
    if not contacts:
        return {'ok': False, 'error': 'segment has no subscribed contacts'}
    accepted = 0
    failed = 0
    for i in range(0, len(contacts), batch_size):
        batch = contacts[i:i + batch_size]
        resp = requests.post(f'{ESP_URL}/campaigns/{campaign_id}/send', json={'recipients': batch}, headers=_headers(), timeout=30)
        if resp.status_code == 200:
            accepted += len(batch)
        else:
            failed += len(batch)
    _record_send(campaign_id, segment_id, accepted, failed)
    return {'ok': failed == 0, 'accepted': accepted, 'failed': failed}
